# Resting book for STU001 mirrors spec §3: asks 62/150, 63/200, 65/80 · bids 59/250, 57/300.
STU001_BOOK = {"asks": [(62, 150), (63, 200), (65, 80)], "bids": [(59, 250), (57, 300)]}


def is_seeded() -> bool:
    if not inspect(engine).has_table("users"):
        return False
    with SessionLocal() as db:
        return db.scalar(select(User).limit(1)) is not None


def reset_and_seed() -> None:
    Base.metadata.drop_all(engine)
    Base.metadata.create_all(engine)
    with SessionLocal() as db:
        seed(db, utcnow())


def seed(db, now: datetime) -> None:
    rng = random.Random(2026)
    for uid, role, name in USERS:
        db.add(User(id=uid, role=role, display_name=name))
        db.add(Wallet(user_id=uid))
    for sid, uid, name, uni, year, major, gpas, courses, activities, apps in STUDENTS:
        db.add(User(id=uid, role="STUDENT", display_name=name))
        db.add(Wallet(user_id=uid))
        db.add(Student(id=sid, user_id=uid, university=uni, year=year, major=major, verified=True))
        verified = now - timedelta(days=rng.randint(5, 20))
        db.add(Disclosure(student_id=sid, type="GPA_HISTORY", title="Term GPA (transcript verified)",
                          data={"terms": [{"term": t, "gpa": g, "credits": c} for t, g, c in gpas]},
                          verified_at=verified))
        db.add(Disclosure(student_id=sid, type="COURSE_LOAD", title="Current course load",
                          data={"courses": [{"code": c, "name": n, "credits": cr} for c, n, cr in courses]},
                          verified_at=verified))
        db.add(Disclosure(student_id=sid, type="ACTIVITY", title="Activities", data={"items": activities},
                          verified_at=verified))
        db.add(Disclosure(student_id=sid, type="APPLICATION", title="Applications & awards",
                          data={"items": [{"name": n, "result": r} for n, r in apps]}, verified_at=verified))
    db.flush()
    for uid, role, _ in USERS:
        if role == "TRADER":
            ledger.fund_user(db, uid, MM_CREDITS if uid.startswith("MM_") else TRADER_CREDITS,
                             now=now - timedelta(days=4))
    db.commit()

    for mid, sid, threshold, term, deadline, p0, p1, target, resolved in MARKETS:
        student_name = next(s[2] for s in STUDENTS if s[0] == sid).split(" · ")[0]
        db.add(Market(id=mid, student_id=sid, threshold=threshold, term=term, deadline=deadline,
                      question=f"Will {student_name} earn a {term} GPA of {threshold} or higher?",
                      status="PRICE_DISCOVERY", created_at=now - timedelta(days=4)))
        db.commit()
        market = db.get(Market, mid)
        _simulate_history(db, rng, mid, p0, p1, now)

        if target in ("SCHOLARSHIP_LOCKED", "TRADING", "SETTLED"):
            scholarship_service.lock(db, market, None, now=now - timedelta(minutes=30))
        if target in ("TRADING", "SETTLED"):
            market_service.start_trading(db, market)
        if target == "SETTLED":
            settlement_service.resolve(db, market, resolved)
            settlement_service.settle(db, market, now=now - timedelta(minutes=5))
            continue

        last = market.last_price_cents
        book = STU001_BOOK if mid == "STU001-GPA-2026F" else {
            "asks": [(last + 2, 120), (last + 3, 200), (last + 5, 90)],
            "bids": [(last - 1, 150), (last - 3, 260)],
        }
        t = now - timedelta(minutes=10)
        for price, qty in book["asks"]:
            order_service.place_order(db, "MM_BETA", mid, NO, BUY, LIMIT, 100 - price, qty, now=t)
        for price, qty in book["bids"]:
            order_service.place_order(db, "MM_ALPHA", mid, YES, BUY, LIMIT, price, qty, now=t)


def _simulate_history(db, rng, market_id, p0, p1, now, n=36, hours=72):
    """Random walk from p0 to p1 over `hours`, executed as maker/taker pairs between market makers."""
    for i in range(n):
        frac = i / (n - 1)
        price = round(p0 + (p1 - p0) * frac + rng.uniform(-2.5, 2.5)) if i < n - 1 else p1
        price = max(3, min(97, price))
        qty = rng.choice([10, 20, 25, 40, 50, 75, 100])
        t = now - timedelta(hours=hours * (1 - frac)) - timedelta(minutes=40)
        alpha_yes = order_service.position(db, "MM_ALPHA", market_id, YES)
        if i > 4 and rng.random() < 0.3 and alpha_yes.quantity - alpha_yes.reserved_qty >= qty:
            order_service.place_order(db, "MM_BETA", market_id, YES, BUY, LIMIT, price, qty, now=t)
            order_service.place_order(db, "MM_ALPHA", market_id, YES, SELL, LIMIT, price, qty, now=t)
        else:
            order_service.place_order(db, "MM_ALPHA", market_id, YES, BUY, LIMIT, price, qty, now=t)
            order_service.place_order(db, "MM_BETA", market_id, NO, BUY, LIMIT, 100 - price, qty, now=t)
